  it(`native ${name} ${row.id} variant ${index}`, () => {
    const source = value(row.sourceHex);
    expect(textFunctions[name]!([value(needle), source, { kind: "number", value: start }], host))
      .toEqual(expected === null ? { kind: "error", value: "#VALUE!" } : { kind: "number", value: expected });
    expect(source).toEqual(value(row.sourceHex));
  });
