it("FIND and FINDB clip host text at NUL and reject visible malformed UTF16", () => {
  for (const name of ["FIND", "FINDB"] as const) {
    expect(textFunctions[name]!([{ kind: "string", value: "b\0\ud800" }, { kind: "string", value: "ab\0tail" }], host)).toEqual({ kind: "number", value: 2 });
    expect(() => textFunctions[name]!([{ kind: "string", value: "a" }, { kind: "string", value: "\ud800" }], host)).toThrow();
  }
});
it("FINDB traversal preserves exact falsey cancellation and immutable input", () => {
  for (const reason of [null, false, 0, "", Number.NaN]) {
    const source = { kind: "byte-string", value: "6162".repeat(100) } as const;
    let ticks = 0, observed: unknown = "not-cancelled";
    const cancelled = { ...host, tick() { if (++ticks === 450) throw reason; } };
    try { textFunctions.FINDB!([{ kind: "string", value: "Z" }, source], cancelled); } catch (error) { observed = error; }
    expect(Object.is(observed, reason)).toBe(true);
    expect(ticks).toBe(450);
    expect(source.value).toBe("6162".repeat(100));
  }
});
